	"regexp"
	"sort"
	"strings"
	"sync"
	"time"
)

GOHEAD
cat /tmp/help_go.txt >> /tmp/main_head.go
cat >> /tmp/main_head.go <<'GOHEAD2'

func isMethod(s string) bool {
	up := strings.ToUpper(s)
	switch up {
	case "GET", "POST", "PUT", "DELETE", "PATCH", "HEAD", "OPTIONS":
		return true
	default:
		return false
	}
}

func isTTY() bool {
	fi, err := os.Stdout.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}

func formatSize(n int64) string {
	if n < 1024 {
		return fmt.Sprintf("%d B", n)
	} else if n < 1024*1024 {
		return fmt.Sprintf("%.2f KB", float64(n)/1024)
	} else if n < 1024*1024*1024 {
		return fmt.Sprintf("%.2f MB", float64(n)/1024/1024)
	} else {
		return fmt.Sprintf("%.2f GB", float64(n)/1024/1024/1024)
	}
}

func formatSpeed(bps float64) string {
	if bps < 1024 {
		return fmt.Sprintf("%.2f B/s", bps)
	} else if bps < 1024*1024 {
		return fmt.Sprintf("%.2f KB/s", bps/1024)
	} else if bps < 1024*1024*1024 {
		return fmt.Sprintf("%.2f MB/s", bps/1024/1024)
	} else {
		return fmt.Sprintf("%.2f GB/s", bps/1024/1024/1024)
	}
}

func colorizeJSON(s string) string {
	// keys: "key":
	reKey := regexp.MustCompile(`"([^"]*)"\s*:`)
	s = reKey.ReplaceAllString(s, "\"\x1b[95m$1\x1b[0m\":")
	// string values: : "value" (handle escaped quotes)
	reStr := regexp.MustCompile(`: "((?:\\.|[^"\\])*)"`)
	s = reStr.ReplaceAllString(s, ": \"\x1b[96m$1\x1b[0m\"")
	// numbers/bools/null with comma (with reset)
	reNumComma := regexp.MustCompile(`: (-?\d[\d\.\-eE\+]*|true|false|null),`)
	s = reNumComma.ReplaceAllString(s, ": \x1b[96m$1\x1b[0m,")
	// numbers/bools/null without comma followed by newline or } or ] (without reset - bug)
	reNumNoComma := regexp.MustCompile(`: (-?\d[\d\.\-eE\+]*|true|false|null)(\n|\}|\])`)
	s = reNumNoComma.ReplaceAllString(s, ": \x1b[96m$1$2")
	// stray reset for }, and ],
	s = strings.ReplaceAll(s, "},", "}\x1b[0m,")
	s = strings.ReplaceAll(s, "],", "]\x1b[0m,")
	return s
}

GOHEAD2
cat /tmp/main_head.go | head -n 100
wc -c /tmp/main_head.go
"}

