{"command":"cat >> /tmp/main_head.go <<'GOMAIN'

func buildQuery(data map[string]string) string {
	if len(data) == 0 {
		return ""
	}
	parts := make([]string, 0, len(data))
	for k, v := range data {
		parts = append(parts, url.QueryEscape(k)+"="+url.QueryEscape(v))
	}
	return strings.Join(parts, "&")
}

func main() {
	log.SetFlags(log.Ldate | log.Ltime | log.Lmicroseconds)
	var authFlag, bodyFlag, proxyFlag, printFlag string
	var benchFlag, formFlag, jsonFlag, prettyFlag, insecureFlag, versionFlag, downloadFlag bool
	var benchN, benchC int
	fs := flag.NewFlagSet(os.Args[0], flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	fs.Usage = func() {
		os.Stdout.WriteString(helpText + "\n")
	}
	fs.StringVar(&authFlag, "a", "", "")
	fs.StringVar(&authFlag, "auth", "", "")
	fs.BoolVar(&benchFlag, "b", false, "")
	fs.BoolVar(&benchFlag, "bench", false, "")
	fs.IntVar(&benchN, "b.N", 1000, "")
	fs.IntVar(&benchC, "b.C", 100, "")
	fs.StringVar(&bodyFlag, "body", "", "")
	fs.BoolVar(&formFlag, "f", false, "")
	fs.BoolVar(&formFlag, "form", false, "")
	fs.BoolVar(&jsonFlag, "json", true, "")
	fs.BoolVar(&prettyFlag, "p", true, "")
	fs.BoolVar(&prettyFlag, "pretty", true, "")
	fs.BoolVar(&insecureFlag, "i", false, "")
	fs.BoolVar(&insecureFlag, "insecure", false, "")
	fs.StringVar(&proxyFlag, "proxy", "", "")
	fs.StringVar(&printFlag, "print", "A", "")
	fs.BoolVar(&versionFlag, "v", false, "")
	fs.BoolVar(&versionFlag, "version", false, "")
	fs.BoolVar(&downloadFlag, "d", false, "")
	fs.BoolVar(&downloadFlag, "download", false, "")
	if err := fs.Parse(os.Args[1:]); err != nil {
		os.Exit(2)
	}
	if versionFlag {
		os.Stdout.WriteString("Version: 0.1.0\n")
		os.Exit(2)
	}
	args := fs.Args()
	// bench mode
	if benchFlag {
		doBench(args, authFlag, bodyFlag, proxyFlag, formFlag, jsonFlag, insecureFlag, benchN, benchC)
		return
	}
	// parse method/url/items
	var method, urlStr string
	var items []string
	if len(args) == 0 {
		os.Stdout.WriteString(helpText + "\n")
		os.Exit(2)
	}
	if isMethod(args[0]) {
		method = strings.ToUpper(args[0])
		if len(args) < 2 {
			log.Fatalf("filter.go:35: Miss the URL")
		}
		urlStr = args[1]
		if urlStr == "" {
			os.Stdout.WriteString(helpText + "\n")
			os.Exit(2)
		}
		if len(args) > 2 {
			items = args[2:]
		}
	} else {
		urlStr = args[0]
		if urlStr == "" {
			os.Stdout.WriteString(helpText + "\n")
			os.Exit(2)
		}
		if len(args) > 1 {
			items = args[1:]
		}
		// infer method
		hasData := false
		for _, it := range items {
			if strings.Contains(it, "=") || strings.Contains(it, "@") {
				hasData = true
				break
			}
		}
		if hasData {
			method = "POST"
		} else {
			method = "GET"
		}
	}
	if !strings.Contains(urlStr, "://") {
		urlStr = "http://" + urlStr
	}
	// parse items
	customHeaders := make(map[string]string)
	dataMap := make(map[string]string)
	for _, it := range items {
		if strings.Contains(it, ":") {
			parts := strings.SplitN(it, ":", 2)
			k := parts[0]
			v := ""
			if len(parts) > 1 {
				v = strings.TrimSpace(parts[1])
			}
			customHeaders[k] = v
		} else if strings.Contains(it, "=") {
			parts := strings.SplitN(it, "=", 2)
			k := parts[0]
			v := ""
			if len(parts) > 1 {
				v = parts[1]
			}
			if strings.HasPrefix(v, "@") {
				fpath := v[1:]
				content, err := os.ReadFile(fpath)
				if err != nil {
					log.Fatalf("http.go:86: Read File%s%s", fpath, err)
				}
				v = string(content)
			}
			dataMap[k] = v
		} else if strings.Contains(it, "@") {
			// ignore (file upload legacy, triggers POST but sends nothing)
		} else {
			// ignore
		}
	}
	// build query/body
	var reqBodyStr string
	var reqBodyReader io.Reader
	var contentTypeToSet string
	hasContentTypeToSet := false
	queryStr := ""
	if method == "GET" {
		if len(dataMap) > 0 {
			queryStr = buildQuery(dataMap)
			if strings.Contains(urlStr, "?") {
				urlStr = urlStr + "&" + queryStr
			} else {
				urlStr = urlStr + "?" + queryStr
			}
		}
		if bodyFlag != "" {
			reqBodyStr = bodyFlag
			reqBodyReader = strings.NewReader(reqBodyStr)
		}
	} else {
		if bodyFlag != "" {
			reqBodyStr = bodyFlag
			reqBodyReader = strings.NewReader(reqBodyStr)
			if !formFlag && len(dataMap) > 0 {
				contentTypeToSet = "application/json"
				hasContentTypeToSet = true
			}
		} else {
			if len(dataMap) > 0 {
				if formFlag {
					reqBodyStr = buildQuery(dataMap)
					reqBodyReader = strings.NewReader(reqBodyStr)
					contentTypeToSet = "application/x-www-form-urlencoded"
					hasContentTypeToSet = true
				} else {
					// json
					jb, _ := json.Marshal(dataMap)
					reqBodyStr = string(jb) + "\n"
					reqBodyReader = strings.NewReader(reqBodyStr)
					contentTypeToSet = "application/json"
					hasContentTypeToSet = true
				}
			} else {
				reqBodyReader = nil
				reqBodyStr = ""
			}
		}
	}
	// download filename check before request (to match empty filename error with no stdout)
	var downloadFilename string
	if downloadFlag {
		// parse URL to get path
		parsed, perr := url.Parse(urlStr)
		fname := ""
		if perr == nil {
			p := parsed.Path
			if idx := strings.LastIndex(p, "/"); idx >= 0 {
				fname = p[idx+1:]
			} else {
				fname = p
			}
		} else {
			// fallback: manual
			s := urlStr
			// strip query/fragment
			if idx := strings.Index(s, "?"); idx >= 0 {
				s = s[:idx]
			}
			if idx := strings.Index(s, "#"); idx >= 0 {
				s = s[:idx]
			}
			if idx := strings.LastIndex(s, "/"); idx >= 0 {
				fname = s[idx+1:]
			} else {
				fname = s
			}
		}
		downloadFilename = fname
		if downloadFilename == "" {
			f, ferr := os.Create("")
			if ferr != nil {
				log.Fatalf("bat.go:240: can't create file%s", ferr)
			}
			f.Close()
		}
	}
	// build request
	req, rerr := http.NewRequest(method, urlStr, reqBodyReader)
	if rerr != nil {
		log.Fatalf("bat.go:215: can't get the url %s", rerr)
	}
	// defaults
	req.Header.Set("User-Agent", "bat/0.1.0")
	req.Header.Set("Accept-Encoding", "gzip, deflate")
	var acceptVal string
	if formFlag {
		if jsonFlag {
			acceptVal = "application/json"
		} else {
			acceptVal = "*/*"
		}
	} else {
		if method == "GET" {
			if jsonFlag {
				acceptVal = "application/json"
			} else {
				acceptVal = "*/*"
			}
		} else {
			acceptVal = "application/json"
		}
	}
	req.Header.Set("Accept", acceptVal)
	// custom headers
	for k, v := range customHeaders {
		if strings.EqualFold(k, "Host") {
			req.Host = v
		} else {
			req.Header.Set(k, v)
		}
	}
	// content-type overwrite
	if hasContentTypeToSet {
		req.Header.Set("Content-Type", contentTypeToSet)
	}
	// auth
	if authFlag != "" {
		var authStr string
		if strings.Count(authFlag, ":") == 1 {
			authStr = authFlag
		} else {
			authStr = authFlag + ":"
		}
		enc := base64.StdEncoding.EncodeToString([]byte(authStr))
		req.Header.Set("Authorization", "Basic "+enc)
	}
	// client
	transport := http.DefaultTransport.(*http.Transport).Clone()
	if proxyFlag != "" {
		pstr := proxyFlag
		if !strings.Contains(pstr, "://") {
			pstr = "http://" + pstr
		}
		if pu, perr := url.Parse(pstr); perr == nil {
			transport.Proxy = http.ProxyURL(pu)
		} else {
			// if parse fails, still try? use as is
			transport.Proxy = http.ProxyURL(&url.URL{Host: pstr})
		}
	}
	if insecureFlag {
		transport.TLSClientConfig = &tls.Config{InsecureSkipVerify: true}
	}
	client := &http.Client{Transport: transport}
	// download mode
	if downloadFlag {
		doDownload(client, req, downloadFilename)
		return
	}
	// normal mode
	resp, derr := client.Do(req)
	if derr != nil {
		log.Fatalf("bat.go:215: can't get the url %s", derr)
	}
	defer resp.Body.Close()
	bodyBytes, _ := io.ReadAll(resp.Body)
	isJSON := strings.Contains(resp.Header.Get("Content-Type"), "json")
	tty := isTTY()
	if !tty {
		// piped: only body, leading \n, no colors, no trailing
		os.Stdout.WriteString("\n")
		if prettyFlag && isJSON {
			var buf bytes.Buffer
			if err := json.Indent(&buf, bodyBytes, "", "  "); err != nil {
				log.Fatalf("http.go:122: Response Json Indent: %s", err)
			}
			os.Stdout.WriteString(buf.String())
		} else {
			os.Stdout.WriteString(string(bodyBytes))
		}
		return
	}
	// tty: respect print flag
	showH, showB, showh, showb := false, false, false, false
	if strings.Contains(printFlag, "A") {
		showH, showB, showh, showb = true, true, true, true
	} else {
		if strings.Contains(printFlag, "H") {
			showH = true
		}
		if strings.Contains(printFlag, "B") {
			showB = true
		}
		if strings.Contains(printFlag, "h") {
			showh = true
		}
		if strings.Contains(printFlag, "b") {
			showb = true
		}
	}
	if showH {
		// request line
		uri := req.URL.RequestURI()
		if uri == "" {
			uri = "/"
		}
		proto := req.Proto
		if proto == "" {
			proto = "HTTP/1.1"
		}
		fmt.Fprintf(os.Stdout, "\x1b[95m%s\x1b[0m \x1b[96m%s\x1b[0m \x1b[95m%s\r\x1b[0m\n", method, uri, proto)
		// host first
		hostVal := req.Host
		if hostVal == "" {
			hostVal = req.URL.Host
		}
		fmt.Fprintf(os.Stdout, "\x1b[90m%s\x1b[0m:\x1b[96m %s\r\x1b[0m\n", "Host", hostVal)
		// other headers sorted
		keys := make([]string, 0, len(req.Header))
		for k := range req.Header {
			// skip Host if present in header map? Header map shouldn't contain Host since we set req.Host, but if user set Host via Header.Set? we didn't, we set req.Host. So no Host in map. But just in case, skip Host to avoid duplicate? Original? For Host custom, display shows Host once (first). So skip Host in map.
			if strings.EqualFold(k, "Host") {
				continue
			}
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
